"""Plan 09: build the CLIP candidate vocabulary for the Grounding-DINO -> CLIP
concept-discovery pipeline (a non-generative alternative to the VLM-prompting
pipeline -- CLIP has no text decoder, so it can only *pick* a concept out of
a vocabulary you already have, not write one). Per the user's own call, that
vocabulary is the pool of everything already generated by the VLM-prompting
legs of this plan, deduplicated the same way vlm_concepts_pool.py dedupes a
single VLM's own output.

Usage:
    python vlm_concepts_build_candidate_vocab.py
"""
import re
from pathlib import Path

CUB_DIR = Path(__file__).parent

SOURCE_BANKS = [
    "cub_concepts_qwen2vl_grounded.txt",
    "cub_concepts_gemini_grounded.txt",
    "cub_concepts_llm.txt",
    "cub_concepts_llm2.txt",
]

OUT_PATH = CUB_DIR / "vlm_concepts" / "clip_candidate_vocab.txt"


def normalize(phrase):
    p = phrase.lower().strip()
    p = re.sub(r"^(a|an|the)\s+", "", p)
    p = re.sub(r"[^a-z0-9\s]", "", p)
    p = re.sub(r"\s+", " ", p).strip()
    return p


def main():
    seen = set()
    pooled = []
    per_source_counts = {}
    for bank_name in SOURCE_BANKS:
        path = CUB_DIR / bank_name
        if not path.exists():
            print(f"skip (not found yet): {bank_name}")
            continue
        lines = [line.strip() for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
        added = 0
        for phrase in lines:
            key = normalize(phrase)
            if not key or key in seen:
                continue
            seen.add(key)
            pooled.append(phrase)
            added += 1
        per_source_counts[bank_name] = (len(lines), added)

    OUT_PATH.parent.mkdir(exist_ok=True)
    OUT_PATH.write_text("\n".join(pooled) + "\n", encoding="utf-8")

    print(f"Candidate vocabulary -> {OUT_PATH} ({len(pooled)} unique phrases)")
    for bank_name, (total, added) in per_source_counts.items():
        print(f"  {bank_name}: {total} phrases, {added} new after dedup")


if __name__ == "__main__":
    main()
